use serde_json::Value;use std::collections::HashMap;
pub fn resolve_rig_values(rig:Option<&Value>,values:&HashMap<String,Value>)->HashMap<String,Value>{let mut out=HashMap::new();let Some(r)=rig else{return out};let controls=r.get("controls").and_then(Value::as_array).cloned().unwrap_or_default();let bindings=r.get("bindings").and_then(Value::as_array).cloned().unwrap_or_default();let mut cv=HashMap::new();for c in controls{if let Some(id)=c.get("id").and_then(Value::as_str){cv.insert(id.to_string(),values.get(id).cloned().unwrap_or_else(||c.get("defaultValue").cloned().unwrap_or(Value::Null)));}}for b in bindings{let(cid,lid,path)=(b.get("controlId").and_then(Value::as_str),b.get("layerId").and_then(Value::as_str),b.get("propertyPath").and_then(Value::as_str));if let(Some(cid),Some(lid),Some(path))=(cid,lid,path){if let Some(v)=cv.get(cid){out.insert(format!("{lid}:{path}"),v.clone());}}}out}
